#!/usr/bin/env node
const fs=require("fs"),path=require("path"),crypto=require("crypto"),buildId=crypto.randomUUID(),timestamp=(new Date).toISOString();console.log(`Generating build ID: ${buildId}`),console.log(`Timestamp: ${timestamp}`);const dataDir=path.join(process.cwd(),"_data");fs.existsSync(dataDir)||fs.mkdirSync(dataDir,{recursive:!0});const yamlContent=`# Build ID generated during Netlify build\n# This file is automatically updated during deployment\nbuild_id: "${buildId}"\nbuild_timestamp: "${timestamp}"\n`,outputPath=path.join(dataDir,"build_id.yml");fs.writeFileSync(outputPath,yamlContent,"utf8"),console.log("Build ID file updated successfully!"),console.log(`Written to: ${outputPath}`);